import{_ as t,o as a,c as d,a5 as r}from"./chunks/framework.CslsFoWx.js";const m=JSON.parse(`{"title":"Mise en production — ce qu'il reste à renseigner","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/mise-en-production.md","filePath":"generated/architecture/mise-en-production.md","lastUpdated":null}`),o={name:"architecture/mise-en-production.md"};function s(n,e,i,c,l,u){return a(),d("div",null,[...e[0]||(e[0]=[r('<div><h1 id="mise-en-production-—-ce-qu-il-reste-a-renseigner" tabindex="-1">Mise en production — ce qu&#39;il reste à renseigner <a class="header-anchor" href="#mise-en-production-—-ce-qu-il-reste-a-renseigner" aria-label="Permalink to &quot;Mise en production — ce qu&#39;il reste à renseigner&quot;">​</a></h1><p>Tout est prêt dans le code : il ne reste que des <strong>valeurs</strong> à fournir. Ce document les regroupe ; rien ici ne demande de modifier le code. La Console Vendora affiche au tableau de bord (administrateurs) une liste <strong>« Avant la mise en production »</strong> qui indique, point par point, ce qui est prêt et ce qui reste.</p><h2 id="environnements-dev-test-prod" tabindex="-1">Environnements (dev, test, prod) <a class="header-anchor" href="#environnements-dev-test-prod" aria-label="Permalink to &quot;Environnements (dev, test, prod)&quot;">​</a></h2><p>Le serveur connaît trois environnements, choisis par <strong><code>SPRING_PROFILES_ACTIVE</code></strong> :</p><ul><li><strong>dev</strong> (aucun profil, défaut) : poste du développeur, valeurs par défaut « DEV ONLY » et simulateurs, simple avertissement au démarrage ;</li><li><strong>test / recette</strong> (<code>SPRING_PROFILES_ACTIVE=staging</code>) : comme la production mais avec des données de test ; bacs à sable de paiement, e-reporting, push et SMS activables <strong>explicitement</strong> par variable ; emails <code>MOCK</code> explicite ou SMTP réel limité à la liste blanche <code>POS_MAIL_ALLOWED_RECIPIENTS</code> ;</li><li><strong>prod</strong> (<code>SPRING_PROFILES_ACTIVE=prod</code>) : aucune valeur de développement ni simulateur accepté.</li></ul><p>Hors dev, le serveur <strong>refuse de démarrer</strong> tant qu&#39;une variable obligatoire manque, garde une valeur de développement ou d&#39;exemple (<code>change-me…</code>), ou qu&#39;une clé de jetons fait moins de 32 caractères ; le message liste les variables, jamais leurs valeurs. <code>GET /api/v1/public/environment</code> (public) rend <code>{&quot;environment&quot;:&quot;dev|staging|prod&quot;}</code> pour le bandeau « STAGING ». Images Docker (publiées dans GitHub Container Registry, <code>ghcr.io/ahmedchebbidev/vendora-server</code> et <code>vendora-web</code>, version épinglée par <code>VENDORA_VERSION</code>), fichiers compose, modèles de variables (<code>deploy/env/*.env.example</code>), premier administrateur, sauvegardes et mises à jour : <strong><a href="/VendoraSystem-docs/architecture/environnements">deploy/README.md</a></strong>. Les variables ci-dessous y sont toutes reprises.</p><h2 id="_1-emails-invitations-rappels-d-essai-relances-factures" tabindex="-1">1. Emails (invitations, rappels d&#39;essai, relances, factures) <a class="header-anchor" href="#_1-emails-invitations-rappels-d-essai-relances-factures" aria-label="Permalink to &quot;1. Emails (invitations, rappels d&#39;essai, relances, factures)&quot;">​</a></h2><p>Tout fournisseur SMTP convient (Brevo, Mailjet, OVH, Google Workspace, Amazon SES…). Variables d&#39;environnement du serveur :</p><table tabindex="0"><thead><tr><th>Variable</th><th>Exemple</th><th>Rôle</th></tr></thead><tbody><tr><td><code>POS_MAIL_MODE</code></td><td><code>SMTP</code></td><td><code>MOCK</code> = boîte simulée (développement uniquement)</td></tr><tr><td><code>POS_MAIL_SMTP_HOST</code></td><td><code>smtp-relay.brevo.com</code></td><td>Serveur SMTP du fournisseur</td></tr><tr><td><code>POS_MAIL_SMTP_PORT</code></td><td><code>587</code></td><td>587 (STARTTLS) ou 465 (SSL)</td></tr><tr><td><code>POS_MAIL_SMTP_SECURITY</code></td><td><code>STARTTLS</code></td><td><code>STARTTLS</code>, <code>SSL</code> ou <code>NONE</code> (relais local seulement)</td></tr><tr><td><code>POS_MAIL_SMTP_USERNAME</code> / <code>POS_MAIL_SMTP_PASSWORD</code></td><td>—</td><td>Identifiants fournis par le fournisseur (secret)</td></tr><tr><td><code>POS_MAIL_FROM</code></td><td><code>no-reply@vendora.tn</code></td><td>Adresse d&#39;un domaine authentifié (SPF / DKIM) chez le fournisseur</td></tr><tr><td><code>POS_MAIL_FROM_NAME</code></td><td><code>Vendora</code></td><td>Nom affiché</td></tr><tr><td><code>POS_MAIL_REPLY_TO</code></td><td><code>support@vendora.tn</code></td><td>Adresse de réponse (facultatif)</td></tr><tr><td><code>POS_BACKOFFICE_URL</code></td><td><code>https://app.vendora.tn</code></td><td>Racine des liens envoyés aux commerçants</td></tr></tbody></table><p>Vérification : <strong>Console › Paramètres › Emails</strong> affiche l&#39;état (sans aucun secret) et envoie un email de test ; en cas d&#39;échec, la cause s&#39;affiche (authentification refusée, délai…).</p><p>Alternative au SMTP : <strong>API HTTPS de Brevo</strong> (<code>POS_MAIL_MODE=BREVO</code>, <code>POS_MAIL_BREVO_API_KEY</code>), utile quand l&#39;hébergeur bloque les ports SMTP ; l&#39;adresse <code>POS_MAIL_FROM</code> doit être un expéditeur validé chez Brevo (domaine authentifié SPF / DKIM en production).</p><h2 id="_2-facturation-identite-tva-mentions-legales" tabindex="-1">2. Facturation : identité, TVA, mentions légales <a class="header-anchor" href="#_2-facturation-identite-tva-mentions-legales" aria-label="Permalink to &quot;2. Facturation : identité, TVA, mentions légales&quot;">​</a></h2><p>À saisir dans <strong>Console › Paramètres › Facturation</strong> (administrateur), sans redéploiement :</p><ul><li>société éditrice : raison sociale, forme, capital, adresse, pays, immatriculation (RCS / SIREN, registre national…), identifiant fiscal (n° de TVA, matricule fiscal), email, banque, IBAN, BIC ;</li><li><strong>TVA par pays du client</strong> (code ISO ou <code>*</code>), avec sa mention et l&#39;autoliquidation B2B si besoin ;</li><li>mentions légales du pied de facture (pénalités de retard, indemnité forfaitaire…) ;</li><li>puis, une fois validé par le comptable, cocher <strong>« validées par le comptable »</strong> : la mention « en attente de validation comptable » disparaît des factures suivantes.</li></ul><p>Chaque facture garde une copie figée de ces paramètres : les factures déjà émises ne changent jamais.</p><h2 id="_3-base-de-donnees-et-cles-des-jetons" tabindex="-1">3. Base de données et clés des jetons <a class="header-anchor" href="#_3-base-de-donnees-et-cles-des-jetons" aria-label="Permalink to &quot;3. Base de données et clés des jetons&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Rôle</th></tr></thead><tbody><tr><td><code>POS_DB_URL</code></td><td>Adresse JDBC de PostgreSQL (<code>jdbc:postgresql://hôte:5432/pos</code>)</td></tr><tr><td><code>POS_DB_APP_PASSWORD</code></td><td>Mot de passe du rôle applicatif <code>pos_app</code> (soumis à la RLS)</td></tr><tr><td><code>POS_DB_OWNER_USER</code> / <code>POS_DB_OWNER_PASSWORD</code></td><td>Propriétaire des tables (migrations, flux d&#39;authentification)</td></tr><tr><td><code>POS_AUTH_JWT_SECRET</code></td><td>Clé des jetons des magasins (≥ 32 caractères)</td></tr><tr><td><code>POS_PAYMENTS_CREDENTIALS_KEY</code></td><td>Clé AES-256 (32 octets en base64) des identifiants des connecteurs de paiement</td></tr><tr><td><code>POS_PUBLIC_URL</code></td><td>Racine publique des reçus digitaux (<code>/r/{jeton}</code>)</td></tr></tbody></table><p>Tant qu&#39;une valeur de développement est utilisée pour une clé, la console le signale dans « Avant la mise en production ».</p><h2 id="_4-console-vendora" tabindex="-1">4. Console Vendora <a class="header-anchor" href="#_4-console-vendora" aria-label="Permalink to &quot;4. Console Vendora&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Rôle</th></tr></thead><tbody><tr><td><code>POS_PLATFORM_JWT_SECRET</code></td><td>Clé des jetons de la console (≥ 32 caractères, différente de celle des magasins)</td></tr><tr><td><code>POS_PLATFORM_DB_PASSWORD</code></td><td>Mot de passe du rôle base <code>pos_platform</code></td></tr><tr><td><code>POS_CONSOLE_URL</code></td><td>Domaine de la console (liens de configuration des membres)</td></tr></tbody></table><p>Premier administrateur : <code>--create-platform-admin=vous@exemple.fr --platform-admin-name=Prénom</code> sur le serveur (avec Docker : <code>docker compose … run --rm server --create-platform-admin=…</code>, voir deploy/README.md §3).</p><h2 id="_5-pages-publiques-vendora-presentation-tarifs-devis" tabindex="-1">5. Pages publiques Vendora (présentation, tarifs, devis) <a class="header-anchor" href="#_5-pages-publiques-vendora-presentation-tarifs-devis" aria-label="Permalink to &quot;5. Pages publiques Vendora (présentation, tarifs, devis)&quot;">​</a></h2><p>Une fois l&#39;API hébergée en HTTPS, renseigner son adresse <strong>une fois</strong> :</p><ul><li>dans <code>site/data/vendora-public.json</code> (<code>&quot;apiUrl&quot;: &quot;https://api.vendora.tn&quot;</code>), ou</li><li>à la publication : <code>VENDORA_API_URL=https://api.vendora.tn ./scripts/publish.sh</code>.</li></ul><p>Effets : les tarifs sont lus <strong>en direct</strong> dans le catalogue de la console (<code>GET /api/v1/public/plans</code>) et les demandes de devis arrivent dans <strong>Console › Demandes de devis</strong>. Sans adresse (aujourd&#39;hui), la page affiche la copie des tarifs prise à la publication (<code>site/data/vendora-plans.json</code>, lue sur le serveur local ou sur <code>VENDORA_PLANS_SOURCE</code>) et le formulaire ouvre un email pré-rempli. Une adresse non HTTPS est refusée à la publication.</p><h2 id="_6-module-fiscal-purge-du-detail-apres-6-ans" tabindex="-1">6. Module fiscal : purge du détail après 6 ans <a class="header-anchor" href="#_6-module-fiscal-purge-du-detail-apres-6-ans" aria-label="Permalink to &quot;6. Module fiscal : purge du détail après 6 ans&quot;">​</a></h2><p>La purge <strong>tracée</strong> du détail des ventes de plus de 6 ans (spec 15 RG-FISC-10/13) est <strong>désactivée par défaut</strong> (développement, tests, recette). En production, l&#39;activer explicitement :</p><table tabindex="0"><thead><tr><th>Variable</th><th>Rôle</th></tr></thead><tbody><tr><td><code>POS_FISCAL_PURGE_ENABLED</code></td><td><code>true</code> pour lancer la tâche quotidienne (défaut <code>false</code>)</td></tr><tr><td><code>POS_FISCAL_PURGE_CRON</code></td><td>Horaire de la tâche (cron Spring, défaut <code>0 30 3 * * *</code> = 03:30, heure du serveur)</td></tr><tr><td><code>POS_FISCAL_PURGE_RETENTION_YEARS</code></td><td>Durée de conservation du détail (défaut <code>6</code> ; toute valeur plus petite est ramenée à 6)</td></tr></tbody></table><p>Ce que fait la tâche, magasin par magasin : elle supprime le détail ligne à ligne (ventes scellées : lignes et paiements) antérieur à aujourd&#39;hui − 6 ans <strong>seulement s&#39;il est couvert par une archive fiscale scellée</strong> (empreintes revérifiées, archive générée après la réception des ventes), caisse par caisse et sans trou (elle s&#39;arrête à la première vente non couverte et garde toujours le dernier maillon de chaque caisse). Les clôtures, le total perpétuel, les Z, le JET et les archives ne sont <strong>jamais</strong> purgés. Chaque purge est inscrite au journal des événements techniques (JET, type <code>PURGE</code> : période, volumes, archives de référence) et dans <strong>Conformité fiscale › Archives fiscales › Purges du détail</strong>. Avant de l&#39;activer : vérifier que les archives annuelles des années concernées existent (sans archive, rien n&#39;est purgé).</p></div>',1)])])}const v=t(o,[["render",s]]);export{m as __pageData,v as default};
